SELECT   c.id AS "Id do Curso",   c.fullname AS "Nome do Curso",   cc.name AS "Categoria do Curso",   fb.name AS "Nome da Pesquisa",   q.name AS "Pergunta",   COALESCE(CAST(cfd_carga.value AS DECIMAL), 0) AS "Carga Horária",    SUBSTRING_INDEX(     CASE       WHEN q.presentation LIKE 'r>>%'         AND a.value REGEXP '^[0-9]+$' THEN TRIM(           SUBSTRING_INDEX(             SUBSTRING_INDEX(               CONCAT(SUBSTRING_INDEX(q.presentation, '>>', -1), '|'),               '|',               (a.value + 1)             ),             '|',             -1           )         )       ELSE IFNULL(a.value, 'Resposta não identificada')     END,     '<<<<<',     1   ) AS "Resposta",    COUNT(DISTINCT fc.id) AS "Qtd por Resposta",    (     SELECT COUNT(DISTINCT fc_sub.id)     FROM mdl_feedback_completed fc_sub     JOIN mdl_feedback_value a_sub ON a_sub.completed = fc_sub.id     WHERE       fc_sub.feedback = fb.id       AND a_sub.item = q.id       AND a_sub.value IS NOT NULL       AND TRIM(a_sub.value) <> ''   ) AS "Total de Respostas",    ROUND(     100.0 * COUNT(DISTINCT fc.id) / NULLIF(       (         SELECT COUNT(DISTINCT fc_sub.id)         FROM mdl_feedback_completed fc_sub         JOIN mdl_feedback_value a_sub ON a_sub.completed = fc_sub.id         WHERE           fc_sub.feedback = fb.id           AND a_sub.item = q.id           AND a_sub.value IS NOT NULL           AND TRIM(a_sub.value) <> ''       ),       0     ),     2   ) AS "Distribuição Percentual",    FROM_UNIXTIME(MAX(fc.timemodified)) AS "Data da Última Resposta"  FROM   mdl_feedback fb   JOIN mdl_course c ON c.id = fb.course   JOIN mdl_course_categories cc ON cc.id = c.category   JOIN mdl_feedback_item q ON q.feedback = fb.id   JOIN mdl_feedback_completed fc ON fc.feedback = fb.id   JOIN mdl_feedback_value a ON a.completed = fc.id AND a.item = q.id   INNER JOIN mdl_customfield_data cfd_obs ON cfd_obs.instanceid = c.id   INNER JOIN mdl_customfield_field cff_obs ON cff_obs.id = cfd_obs.fieldid     AND cff_obs.shortname = 'obs'   LEFT JOIN mdl_customfield_data cfd_carga ON cfd_carga.instanceid = c.id     AND cfd_carga.fieldid = 5  WHERE   fb.course IS NOT NULL   AND a.value IS NOT NULL   AND TRIM(a.value) <> ''   AND (cfd_obs.value != '0' OR cfd_obs.value IS NULL)   AND (     q.name = '6 - O que poderia ser melhorado? (Manda aí sua ideia! 🚀)'     OR q.name LIKE '6 - O que você mais gostou no curso%'     OR q.name LIKE '7 - O que poderia ser melhorado no curso%'   )  GROUP BY   c.id,   c.fullname,   cc.name,   fb.id,   fb.name,   q.id,   q.name,   q.presentation,   a.value,   cfd_carga.value  ORDER BY   c.fullname,   fb.name,   q.name,   "Resposta";
